import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const r=JSON.parse('{"title":"Enzi ya Kabla ya Nanga","description":"","frontmatter":{},"headers":[],"relativePath":"sw/71-前锚点时代.md","filePath":"sw/71-前锚点时代.md"}'),k={name:"sw/71-前锚点时代.md"};function w(e,a,o,s,l,m){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="enzi-ya-kabla-ya-nanga" tabindex="-1">Enzi ya Kabla ya Nanga <a class="header-anchor" href="#enzi-ya-kabla-ya-nanga" aria-label="Permalink to &quot;Enzi ya Kabla ya Nanga&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>71</td></tr><tr><td>Moduli</td><td>Enzi za Kihistoria na Matukio Muhimu</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Enzi ya kabla ya nanga, mfumo wa mauaji, kuteketezwa kwa ustaarabu, enzi ya giza, machafuko ya sheria</td></tr></tbody></table><h2 id="_1-sifa-za-msingi-za-enzi-ya-kabla-ya-nanga" tabindex="-1">1. Sifa za Msingi za Enzi ya Kabla ya Nanga <a class="header-anchor" href="#_1-sifa-za-msingi-za-enzi-ya-kabla-ya-nanga" aria-label="Permalink to &quot;1. Sifa za Msingi za Enzi ya Kabla ya Nanga&quot;">​</a></h2><p>Enzi ya Kabla ya Nanga ni enzi ndefu zaidi na ya giza zaidi katika historia ya Hengyuanzhou. Katika enzi hii, hakukuwa na utaratibu wa nanga uliounganishwa katika ulimwengu, sheria za msingi zilikuwa katika hali ya kutawanyika kwa asili, na mgawanyo wa nishati na rasilimali ulifuata kabisa kanuni ya msitu ya &quot;mwenye nguvu anapata&quot;. Mfumo wa ulinzi wa mauaji ulikuwa mtaalamu wa haki kamili wa enzi hii; njia za ulinzi zilikuwa zinashirikiana na watu wachache wenye nguvu na madhehebu, na viumbe wa kawaida katika safu ya chini hawakuwa na njia rasmi ya mageuzi karibu.</p><p>Sifa za msingi za Enzi ya Kabla ya Nanga zinafupishwa kama &quot;ukosefu wa tano&quot;:</p><ul><li><strong>Hakuna nanga</strong>: Hakukuwa na nanga za sheria za kudumu, mtiririko wa nishati ulikuwa unaosumbua, na kizuizi cha viwango kilikuwa chenye uwezo wa chini</li><li><strong>Hakuna utaratibu</strong>: Hakukuwa na mfumo wa ustaarabu uliounganishwa, vita vilikuwa vya kila wakati kati ya viwango, na kuangamizwa kwa rangi kilikuwa cha kawaida</li><li><strong>Hakuna njia</strong>: Hakukuwa na teknolojia ya mawasiliano na usafiri kati ya viwango, na viwango vilikuwa vimetengana kabisa kwa kila moja</li><li><strong>Hakuna uhakika</strong>: Hakukuwa na mifumo ya uhakika wa umma kama elimu, afya, na makazi, na uhai ulitegemea kabisa kwa uwezo wa mtu binafsi</li><li><strong>Hakuna tumaini</strong>: Njia za mageuzi za viumbe katika safu ya chini zilikuwa zimefungwa kabisa, na utawanyiko wa kijamii ulifikia kiwango cha kipekee</li></ul><h2 id="_2-utaratibu-wa-kazi-wa-mfumo-wa-ulinzi-wa-mauaji" tabindex="-1">2. Utaratibu wa Kazi wa Mfumo wa Ulinzi wa Mauaji <a class="header-anchor" href="#_2-utaratibu-wa-kazi-wa-mfumo-wa-ulinzi-wa-mauaji" aria-label="Permalink to &quot;2. Utaratibu wa Kazi wa Mfumo wa Ulinzi wa Mauaji&quot;">​</a></h2><p>Mfumo wa ulinzi wa Enzi ya Kabla ya Nanga ulikuwa na mauaji kama utaratibu wa kazi wa msingi. Mantiki yake ya msingi ilikuwa: nishati ya msingi ya ulimwengu ni mdogo, na mageuzi ya mtu binafsi ni lazima yatoke kwa gharama ya utumiaji wa nishati ya wengine. Watu wenye nguvu walifikia kupanda kwao kwa kumeza nishati, bahati, na hata asili ya watu wenye uwezo wa chini, wakati watu wenye uwezo wa chini wakawa &quot;rasilimali za ulinzi&quot; kwa watu wenye nguvu.</p><p>Aina za kawaida za mfumo wa mauaji zinajumuisha:</p><table tabindex="0"><thead><tr><th>Aina ya Mauaji</th><th>Njia ya Kazi</th><th>Uharibifu kwa Ulimwengu</th></tr></thead><tbody><tr><td>Mauaji ya nishati</td><td>Kutoa moja kwa moja nishati ya ulinzi ya viumbe wengine</td><td>Kusababisha kifo cha mtu binafsi au upotezaji kamili wa uwezo wa ulinzi</td></tr><tr><td>Mauaji ya bahati</td><td>Kupitia uchawi au hafla, kunyang&#39;anya bahati na fursa za wengine</td><td>Kuharibu usawazishaji wa sababu na matokeo, kusababisha majanga ya kiwango cha eneo</td></tr><tr><td>Mauaji ya asili</td><td>Kumeza vipande vya sheria ya msingi ya viumbe wengine</td><td>Kusababisha upotezaji usiorejezeka wa uwezo wa mageuzi</td></tr><tr><td>Mauaji ya eneo</td><td>Watu wenye nguvu wanashinda eneo jima la wanatumia viumbe vya eneo kama rasilimali za ulinzi</td><td>Kusababisha kuangamizwa kwa ustaarabu na jangwani la eneo</td></tr><tr><td>Mauaji ya sheria</td><td>Kuchukua kwa nguvu udhibiti wa sheria ya msingi ya eneo</td><td>Kuharibu mtandao wa sheria, kusababisha kuanguka kwa nafasi</td></tr></tbody></table><p>Mfumo wa mauaji unaweza, kwa muda mfupi, kuunda watu wachache wenye nguvu zaidi, lakini kwa muda mrefu, unatumia uwezo wa mageuzi wa ulimwengu kwa kila wakati, na kusababisha ongezeko la entropy ya jumla ya ulimwengu kwa kasi na kuteketezwa kwa ustaarabu mara kwa mara.</p><h2 id="_3-kuteketezwa-kwa-ustaarabu-na-uharibifu-wa-mzunguko" tabindex="-1">3. Kuteketezwa kwa Ustaarabu na Uharibifu wa Mzunguko <a class="header-anchor" href="#_3-kuteketezwa-kwa-ustaarabu-na-uharibifu-wa-mzunguko" aria-label="Permalink to &quot;3. Kuteketezwa kwa Ustaarabu na Uharibifu wa Mzunguko&quot;">​</a></h2><p>Tukio la kihistoria lenye umakini zaidi wa Enzi ya Kabla ya Nanga ni &quot;kuteketezwa kwa ustaarabu&quot;. Kwa sababu ya utata wa ndani wa mfumo wa mauaji, kila ustaarabu ambao ulikuwa mwangaza mwishowe unaelekea kujiharibu:</p><ol><li><strong>Kipindi cha kuinuka</strong>: Rangi au madhehebu yao huinuka kwa kasi kupitia mauaji na kuanzisha ustaarabu wenye nguvu</li><li><strong>Kipindi cha kilele cha juu</strong>: Ustaarabu unafikia kilele cha nguvu, unakandamiza upinzani ndani, na anapanuza nje kwa mauaji</li><li><strong>Kipindi cha vita vya ndani</strong>: Watu wenye nguvu ndani ya ustaarabu wanapigana kwa rasilimali mdogo, wanatumia nguvu zao</li><li><strong>Kipindi cha kuanguka</strong>: Vita vya ndazi vinaunguza nguvu ya ustaarabu kwa kasi, na wauaji wa nje wanachukua nafasi ya kuingia, na kusababisha kuangamizwa kwa ustaarabu</li><li><strong>Kipindi cha kuteketezwa</strong>: Baada ya kuangamizwa kwa ustaarabu, maarifa na teknolojia yake nyingi zinapotea, na ustaarabu unaofuata unahitaji kuanzia tangu sifuri</li></ol><p>Mzunguko huu wa &quot;kuinuka—kilele cha juu—vita vya ndani—kuanguka—kuteketezwa&quot; umerudiwa mara nyingi katika Enzi ya Kabla ya Nanga. Kila mzunguko umetumia kiasi kikubwa cha asili ya ulimwengu, na kusababisha kiwango cha mageuzi cha jumla cha ulimwengu kukaa kimya au hata kurudi nyuma kwa muda mrefu.</p><h2 id="_4-dalili-za-mwisho-wa-enzi-ya-kabla-ya-nanga" tabindex="-1">4. Dalili za Mwisho wa Enzi ya Kabla ya Nanga <a class="header-anchor" href="#_4-dalili-za-mwisho-wa-enzi-ya-kabla-ya-nanga" aria-label="Permalink to &quot;4. Dalili za Mwisho wa Enzi ya Kabla ya Nanga&quot;">​</a></h2><p>Katika mwisho wa Enzi ya Kabla ya Nanga, ulimwengu ulionyesha mfululizo wa dalili za mabadiliko:</p><ul><li><strong>Kuzidika kwa machafuko ya sheria</strong>: Mauaji ya muda mrefu yameharibu mtandao wa sheria kwa kasi, matukio ya kuanguka kwa nafasi yamekuwa ya kawaida, na kizuizi cha viwango kimekuwa nyembamba zaidi</li><li><strong>Kukosa kwa uwezo wa uhai</strong>: Nishati ya msingi inayoweza kuuliwa inakuwa ndogo zaidi, na ushindani wa rasilimali kati ya watu wenye nguvu umekuwa mkali</li><li><strong>Chanzo cha wazo la kupinga mauaji</strong>: Baadhi ya watu wenye busara walianza kuzingatia upungufu wa msingi wa mfumo wa mauaji na kuweka wazo la awali la mageuzi ya usirikisho</li><li><strong>Kuongezeka kwa mawasiliano kati ya viwango</strong>: Kizuizi cha viwango kukua nyembamba kumeruhusu mawasiliano makubwa kati ya viwango tofauti, na kufanya ubadilishaji wa mawazo kati ya viwango kuwa uwezekano</li><li><strong>Kuonekana kwa wagombea wa nanga wa kizazi cha kwanza</strong>: Katika baadhi ya pembe za ulimwengu, viumbe maalum vyaweza kutengeneza sauti ya asili na mtandao wa sheria; walikuwa ni watangulizi wa watu wao watakaoteka nanga ya kizazi cha kwanza katika siku zijazo</li></ul><p>Dalili hizi zinaonyesha kwamba mfumo wa mauaji umefikia mwisho wake, na ulimwengu unaita aina mpya kabisa ya ustaarabu.</p><h2 id="_5-urithi-wa-kihistoria-wa-enzi-ya-kabla-ya-nanga" tabindex="-1">5. Urithi wa Kihistoria wa Enzi ya Kabla ya Nanga <a class="header-anchor" href="#_5-urithi-wa-kihistoria-wa-enzi-ya-kabla-ya-nanga" aria-label="Permalink to &quot;5. Urithi wa Kihistoria wa Enzi ya Kabla ya Nanga&quot;">​</a></h2><p>Ingawa Enzi ya Kabla ya Nanga ilikuwa ya giza, haikuwa kabisa bila thamani. Imeacha urithi muhimu wa kihistoria kwa ustaarabu wa usirikisho wa nanga uliofuata:</p><ul><li><strong>Urithi wa masomo</strong>: Kushindwa kwa mara kwa mara kwa mfumo wa mauaji kutoa mfano mbaya wa kina zaidi kwa ustaarabu wa usirikisho, na kuthibitisha kwamba njia ya mauaji haifanyi kazi</li><li><strong>Urithi wa maarifa</strong>: Ingawa maarifa mengi yamepotea katika kuteketezwa kwa ustaarabu, baadhi ya njia za ulinzi na uelewa wa sheria zimebaki kwa njia anuwai, na kuwa chanzo cha vifaa kwa mifumo mia tatu ya ulinzi wa msingi</li><li><strong>Urithi wa uhai</strong>: Aina anuwai za uhai zilizosaliisha katika enzi ya giza ndefu zilikuwa msingi wa rangi kwa usirikisho wa kila rangi katika siku zijazo</li><li><strong>Urithi wa mapenzi</strong>: Hamu ya kudumu ya viumbe katika safu ya chini kwa haki na tumaini ilikuwa nguvu ya roho ya msingi zaidi ya utekaji wa nanga</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Enzi ya Kabla ya Nanga ni &quot;usiku wa kabla ya giza&quot; katika historia ya Hengyuanzhou. Urefu wake na giza lake, kinyume chake, vinaonyesha thamani na lazima ya kuzaliwa kwa ustaarabu wa usirikisho wa nanga. Kuelewa Enzi ya Kabla ya Nanga ni kuelewa mizizi ya kihistoria ya msingi wa ustaarabu wa usirikisho wa &quot;kupinga mauaji, kushirikisha usirikisho&quot; — hii si hubiri ya maadili ya kiabstract, bali ni masomo ya damu na machozi yaliyobadilishwa kwa uharibifu wa ustaarabu wengi.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>70-Jedwali la Jumla la Mgawanyo wa Enzi</li><li>72-Enzi ya Uamsho wa Nanga</li><li>04-Mpango wa Msingi wa Kupinga Mauaji</li></ul>',26)])])}const z=i(k,[["render",w]]);export{r as __pageData,z as default};
